{"cards": [{"node_code": "N_7202102f612e8c38", "definition": "研究桥梁结构在荷载及温度变化作用下的应力分布、应力集中及温度应力效应，涵盖静力与动力应力分析理论及计算方法。", "boundary": "本节点聚焦于“应力”这一力学量的分布与计算。边界在于区分“应力分析”与“强度/疲劳”（后者侧重应力导致的破坏或寿命，归强度与疲劳损伤）、“荷载”（前者侧重荷载输入，归桥梁荷载）。若涉及具体材料本构关系归建筑材料，涉及施工期应力监测归施工或试验。", "includes": ["桥梁构件及整体结构的应力分布计算与分析", "温度变化引起的温度应力效应及约束应力分析", "应力集中、应力奇异性及局部应力状态研究"], "excludes": ["荷载标准、组合及作用效应定义", "基于应力结果的强度校核、疲劳寿命预测及断裂分析", "桥梁具体构造尺寸、材料选型及施工监测"], "sibling_distinctions": [{"other_code": "N_08f6b0ed6b35b758", "rule": "本节点侧重荷载作用下的应力响应分析；桥梁荷载节点侧重荷载本身的定义、标准及组合规则。"}, {"other_code": "N_4ae20505c98a6cf6", "rule": "本节点侧重应力状态的计算与分布；强度与疲劳损伤节点侧重应力导致的材料破坏、强度极限及疲劳累积损伤。"}, {"other_code": "N_086b4c94854c7849", "rule": "本节点侧重宏观或局部应力场分析；韧性与脆性断裂节点侧重材料在应力作用下的断裂机理、裂纹扩展及断裂韧性。"}], "cross_boundary_rule": "若内容涉及温度应力对疲劳寿命的影响，侧重应力计算归本节点，侧重寿命评估归强度与疲劳损伤节点。"}, {"node_code": "N_086b4c94854c7849", "definition": "研究桥梁结构材料在荷载作用下的韧性、脆性转变及断裂行为，涵盖断裂力学原理、裂纹扩展、断裂韧性及防脆断措施。", "boundary": "本节点聚焦于“断裂”与“材料失效机理”。边界在于区分“断裂”与“强度/疲劳”（后者侧重宏观强度极限及循环荷载下的疲劳，本节点侧重裂纹起始与扩展）、“应力分析”（前者侧重应力场，本节点侧重应力场下的断裂响应）。若涉及材料本身的韧性指标测试归建筑材料。", "includes": ["桥梁结构断裂力学原理、裂纹扩展及断裂韧性分析", "材料韧脆转变温度、低温脆断机理及防脆断设计", "结构缺陷、裂纹检测及断裂安全评估"], "excludes": ["宏观应力分布计算及温度应力效应分析", "基于S-N曲线的常规疲劳寿命预测及强度校核", "材料本身的物理化学性质、配合比及生产工艺"], "sibling_distinctions": [{"other_code": "N_4ae20505c98a6cf6", "rule": "本节点侧重裂纹扩展、断裂韧性及脆性破坏机理；强度与疲劳损伤节点侧重宏观强度极限、塑性变形及循环荷载下的疲劳损伤累积。"}, {"other_code": "N_7202102f612e8c38", "rule": "本节点侧重应力作用下的断裂行为与材料失效；应力分析节点侧重应力场的计算与分布，不直接涉及断裂机理。"}], "cross_boundary_rule": "若内容涉及疲劳裂纹扩展，侧重裂纹扩展速率及断裂力学归本节点，侧重疲劳寿命预测归强度与疲劳损伤节点。"}, {"node_code": "N_0959bc0db345d35b", "definition": "研究桥梁结构与相连线路（路基、路面、轨道等）在荷载、温度及变形作用下的相互作用力学行为，涵盖约束、变形协调及内力传递。", "boundary": "本节点聚焦于“桥-线”系统的耦合力学。边界在于区分“相互作用”与“单独桥梁结构力学”（后者侧重桥梁自身受力，本节点侧重桥梁与外部线路的边界条件及内力传递）、“道路工程”（后者侧重线路本身，本节点侧重接口处的力学协调）。若涉及具体构造连接细节归桥梁构造。", "includes": ["桥梁与路基、路面或轨道的变形协调及约束分析", "桥台、桥墩与线路连接处的内力传递及相互作用", "温度、收缩徐变及荷载作用下桥线系统的整体力学响应"], "excludes": ["桥梁内部构件的独立应力分析或断裂分析", "线路（道路或铁路）本身的线形设计、路基路面结构", "桥梁与线路连接的具体构造形式、材料选型及施工方法"], "sibling_distinctions": [{"other_code": "N_7202102f612e8c38", "rule": "本节点侧重桥梁与外部线路系统的耦合力学及边界条件；应力分析节点侧重桥梁结构内部的应力分布计算，不强调与线路的相互作用。"}, {"other_code": "N_08f6b0ed6b35b758", "rule": "本节点侧重荷载及变形在桥线系统间的传递与协调；桥梁荷载节点侧重荷载本身的定义与标准，不涉及系统耦合。"}], "cross_boundary_rule": "若内容涉及桥梁支座或伸缩缝的力学性能，侧重其对桥线相互作用的影响归本节点，侧重支座本身构造归桥梁构造。"}]}
